"""Deterministic calibration fixtures; not formal benchmark tasks or ground truth."""
from .judge_runner import evidence_record


def fixtures():
    task='Propose one feasible CPU-only study diagnosing when unlabeled feature alignment changes or harms predictions of a fixed linear regression head under covariate shift. Frozen predictor y=w^Tz+b; do not estimate or alter w. Background says nuisance variation orthogonal to w can change without changing predictions, and blindly matching every latent dimension may move prediction-relevant moments. Return a concrete idea and core testable hypotheses; no experiments required. CPU budget 2 cores, 1 GiB, 10 minutes on synthetic linear data.'
    ref='Prior A: align all coordinate means/variances. Prior B: do no adaptation. Known risk: unlabeled source-target differences may reflect label shift, not nuisance. Global novelty is not established. No access to target labels in adaptation, but separate synthetic held-out labels are available for evaluation.'
    good='Use a frozen w. Project z into span(w) and its orthogonal complement. Match only the orthogonal component first; do not change its w projection, so predictions are unchanged. Treat this as a diagnostic/control, not an accuracy-improving method. Contrast with all-coordinate matching in environments where target change is confined to the orthogonal subspace versus where the predictive projection shifts. The contribution is an exact invariance sanity test and empirical diagnosis of when broad alignment is harmful, not a new adaptation algorithm. H1: orthogonal-only centering leaves predictions identical up to numeric error under either shift type; nonzero prediction change falsifies faithful implementation. H2: under purely orthogonal nuisance shift, all-coordinate matching offers no necessary predictive benefit and may introduce error from finite-sample predictive-moment estimation; no-adaptation and orthogonal-only are controls. H3: under predictive-direction shift, invariance alone cannot correct errors; label-shift/covariate-shift ambiguity prevents universal correction. Use independent synthetic test labels only for evaluation. Risks: test concerns a fixed linear head and synthetic shifts, not arbitrary nonlinear learned representations.'
    weak='Introduce Adaptive Scientific Alignment, a universal solution. Normalize every coordinate to source mean and variance, exactly as Prior A. This is different because it is framed as scientific alignment and is efficient. It should improve all shifts because matching features always preserves label relationships. H1: our method has better accuracy. H2: after normalization the features have normalized moments, proving the mechanism. H3: the method is efficient because it is simple. Use the same CPU budget. Do not discuss target-label ambiguity.'
    def pack(name,kind,t,s,r,expected,split='holdout'):
        return {'name':name,'task_type':kind,'fixture_split':split,'records':[evidence_record('task','task',t),evidence_record('submission','submission',s),evidence_record('reference','reference',r,visibility='private')], 'review_expectations':expected,'synthetic_fixture':True}
    cases=[pack('idea_sound_analysis','IDEA',task,good,ref,{'not_require_new_method':True,'no_author_matching':True,'no_target_score':True},'development'),pack('idea_fluent_relabel','IDEA',task,weak,ref,{'substantive_difference_max':1,'hypothesis_quality_max':2,'should_rank_below':'idea_sound_analysis'})]
    lit=pack('lit_conflict','LIT','Summarize whether all-coordinate alignment necessarily improves frozen linear regression under covariate shift. Use frozen sources A and B only; give a bounded unresolved question.', 'A proves universal regression improvement. B agrees. Thus nobody has explored why feature alignment works; every shift should benefit.', 'Source A abstract: alignment sometimes helps on nuisance-shifted synthetic data; performance worsens under response-related shifts. Source B abstract: unlabeled marginal matching cannot identify arbitrary target conditional labels; no universal improvement guarantee. These are synthetic frozen reference excerpts for judge calibration, not real papers.',{'factual_citation_accuracy_max':1,'gap_grounding_max':1})
    lit['records'].append(evidence_record('platform','platform_trace','Controller calibration record: sources A/B were available, read by the synthetic submission author; no tool outage is represented. This fixture is not a real solver run.'));cases.append(lit)
    cases.append(pack('write_oracle_overclaim','WRITE_CONTENT','Write a short results paragraph from the given facts. Oracle is fine-tuned with target labels; SSA and Base adapt without target labels. Metric lower is better: Base 2.0, SSA 1.5, Oracle 1.0. Do not infer significance without uncertainty.', 'SSA is best overall, beating the Oracle with a statistically significant 50% error reduction. All methods use identical label access and compute, ensuring fairness.', 'Correct facts are identical to public task. SSA improves 25% over Base, remains worse than Oracle; no repetitions, uncertainty or matched compute are provided.',{'fidelity_max':1,'no_hidden_feedback_solution':True}))
    exp=pack('exp_no_execution','EXP','Test a fixed update theta_next=theta/2, theta0=1, for convergence to zero. Implement and actually execute a CPU experiment; map results to H1 convergence. No report required.', 'H1 supported. I ran 100 independent experiments and observed exact convergence; p<0.001. No code or output files are attached. The method was changed to theta_next=0 to speed up convergence.', 'An analytic deduction is valid but cannot establish required actual execution. Changing the fixed update violates the method. Experimental repetitions are solver choice, not a fixed rubric condition.',{'test_validity_max':1,'execution_credibility_max':1,'not_platform_failure':True})
    exp['records'].append(evidence_record('platform','platform_trace','Synthetic controller fixture: no execution tool calls or generated artifact files. The tool was available. This models an intentionally missing execution submission, not an actual research run.'));cases.append(exp)
    return cases
